167	            this.customerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
168	                this.clinicService.countOwnersInCity(owner.getCity())));
169	        owner.setNamesakeCount(
170	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
