150	     */
151	    public String getMembershipTier() {
152	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
153	        boolean hasEmail = this.email != null && !this.email.isEmpty();
154	        return unique && hasEmail ? "SILVER" : "BRONZE";
155	    }
156	
157	    /**
158	     * Fixed city-to-region lookup backing {@link #getLocality()}. Cities absent from this
159	     * table derive the locality {@code "UNKNOWN"}.
160	     */
161	    private static final Map<String, String> CITY_REGIONS =
162	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
163	
164	    /**
165	     * The owner's locality: the canonical region derived from {@link #getCity() city} using the
166	     * fixed {@link #CITY_REGIONS} table, or {@code "UNKNOWN"} when the city is not in the table.
167	     */
168	    public String getLocality() {
