172	    /**
173	     * Resolve the effective registration date before persisting: default it to the server's
174	     * current date when none was supplied, then roll it forward off weekends so a newly
175	     * registered owner always has a business-day registration date. Every value derived from it
176	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
177	     * date.
178	     */
179	    @PrePersist
